import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse counts once
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    cc = cd = dc = dd = 0
    for m, o in history:
        if m == 'C':
            my_c += 1
        else:
            my_d += 1
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1

    my_last, opp_last = history[-1]

    def opp_recent_def(k):
        s = 0
        start = n - k if n - k > 0 else 0
        for i in range(start, n):
            if history[i][1] == 'D':
                s += 1
        return s

    def opp_recent_coop(k):
        s = 0
        start = n - k if n - k > 0 else 0
        for i in range(start, n):
            if history[i][1] == 'C':
                s += 1
        return s

    # Opponent cooperation rate
    coop_rate = opp_c / float(n)

    # Endgame: tight defection against weak cooperators, but stay gentle with committed cooperators
    if n >= 96:
        if coop_rate >= 0.82:
            return 'C'
        if coop_rate >= 0.6:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # If opponent is overwhelmingly cooperative, keep mutual cooperation.
    if coop_rate >= 0.9:
        # Rare probe late but only far from endgame
        if n < 70 and n >= 25 and rng.random() < 0.012:
            return 'D'
        return 'C'

    # First couple rounds: cooperate (repair/start signal)
    if n <= 2:
        return 'C'

    # Detect streak of opponent actions
    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    # Long defection streak: give a short punishment, then invite cooperation.
    if opp_last == 'D' and same_count >= 4:
        if same_count >= 8:
            # Deep mutual defection: test cooperation occasionally for repair.
            if rng.random() < 0.22:
                return 'C'
            return 'D'
        # Short punishment, then a cooperative probe.
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Long cooperation streak: preserve it, with rare late probes only early enough to recover.
    if opp_last == 'C' and same_count >= 5:
        if n < 85 and n >= 20 and rng.random() < 0.02:
            return 'D'
        return 'C'

    recent_def = opp_recent_def(6)
    recent_coop = opp_recent_coop(6)

    # Opponent defecting heavily: punish, but don't lock in forever.
    if recent_def >= 5:
        if rng.random() < 0.18:
            return 'C'
        return 'D'

    if recent_def >= 4:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # If we recently defected and opponent cooperates, forgive promptly to restore CC.
    if opp_last == 'C':
        if my_last == 'D':
            # Repair: strong preference for cooperation.
            if rng.random() < 0.9:
                return 'C'
            return 'D'
        # Both cooperating: stay cooperative.
        if opp_d * 3 <= n and rng.random() < 0.02 and n < 80 and n >= 30:
            return 'D'
        return 'C'

    # Opponent defected just now.
    if opp_last == 'D':
        if my_last == 'D':
            # Mutual defection: escape the trap with a cooperative probe fairly often.
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        # We cooperated, they defected: single-round punishment then conciliatory retry.
        if same_count >= 2:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # One-off defection: brief punishment, then forgive quickly.
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Fallback: cooperate to preserve any established cooperation.
    if coop_rate >= 0.6:
        return 'C'
    if coop_rate <= 0.3:
        return 'D'
    return 'C' if rng.random() < 0.75 else 'D'
